async function downloadHeritageImage(image, index) {
  const candidates = [...new Set([image.media_url, image.original_url].filter(Boolean))];
  let lastError;
  for (const url of candidates) {
    for (let attempt = 0; attempt < 3; attempt++) {
      try {
        const response = await fetch(url, {
          headers: {
            "user-agent": "FlyYab-Heritage365/1.1 (https://flyyab.ir)",
            accept: "image/jpeg,image/png,image/webp,image/*;q=0.8"
          }
        });
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        const contentType = String(response.headers.get("content-type") || "").split(";")[0].trim().toLowerCase();
        if (!contentType.startsWith("image/")) throw new Error(`نوع فایل نامعتبر: ${contentType || "unknown"}`);
        const declaredSize = Number(response.headers.get("content-length") || 0);
        if (declaredSize > 9.5 * 1024 * 1024) throw new Error("حجم تصویر بیش از حد مجاز بله است");
        const bytes = await response.arrayBuffer();
        if (bytes.byteLength < 10 * 1024) throw new Error("فایل تصویر ناقص است");
        if (bytes.byteLength > 9.5 * 1024 * 1024) throw new Error("حجم تصویر بیش از حد مجاز بله است");
        return {
          image,
          bytes,
          contentType,
          filename: `heritage-${String(index + 1).padStart(2, "0")}.${heritageImageExtension(contentType)}`
        };
      } catch (error) {
        lastError = error;
        if (attempt < 2) await wait(500 * (attempt + 1));
      }
    }
  }
  throw new Error(`دریافت تصویر ${index + 1} ناموفق بود: ${lastError?.message || "خطای نامشخص"}`);
}
