async function downloadWikipediaFeaturedPicture(featured) {
  let lastError;
  for (let attempt = 0; attempt < 3; attempt++) {
    try {
      const response = await fetch(featured.photoUrl, {
        headers: { "user-agent": WIKIMEDIA_USER_AGENT, accept: "image/jpeg,image/png,image/webp,image/*;q=0.8" }
      });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      const contentType = String(response.headers.get("content-type") || featured.mime || "").split(";")[0].toLowerCase();
      if (!["image/jpeg", "image/png", "image/webp"].includes(contentType)) throw new Error(`نوع فایل نامعتبر: ${contentType || "unknown"}`);
      const declaredSize = Number(response.headers.get("content-length") || 0);
      if (declaredSize > 9.5 * 1024 * 1024) throw new Error("حجم نگاره بیش از حد مجاز بله است");
      const bytes = await response.arrayBuffer();
      if (bytes.byteLength < 10 * 1024) throw new Error("فایل نگاره ناقص است");
      if (bytes.byteLength > 9.5 * 1024 * 1024) throw new Error("حجم نگاره بیش از حد مجاز بله است");
      return { bytes, contentType };
    } catch (error) {
      lastError = error;
      if (attempt < 2) await wait(500 * (attempt + 1));
    }
  }
  throw new Error(`دریافت فایل نگاره ناموفق بود: ${lastError?.message || "خطای نامشخص"}`);
}
