function deliveryActivationCoversSlot(activation, date, slotTime) {
  if (!activation?.tehranDate) return false;
  if (date > activation.tehranDate) return true;
  if (date < activation.tehranDate) return false;
  return deliveryTimeMinutes(slotTime) >= deliveryTimeMinutes(activation.tehranTime || "23:59");
}
async function runDailyDeliveryWatchdog(env, now = new Date()) {
  const date = currentTehranIso(now);
  const currentMinutes = deliveryTimeMinutes(clock(now));
  const [{ activation }, record] = await Promise.all([getSchedulerHealth(env), getDailyDeliveryHealth(env, date)]);
  const alerts = [];
  for (const slot of DAILY_DELIVERY_SLOTS) {
    if (currentMinutes < deliveryTimeMinutes(slot.time) + DELIVERY_HEALTH_GRACE_MINUTES) continue;
    if (!deliveryActivationCoversSlot(activation, date, slot.time)) continue;
    const existing = record.slots?.[slot.id];
    if (existing && DELIVERY_TERMINAL_STATUSES.has(existing.status)) continue;
    let status = "MISSED";
    let code = "CRON_SLOT_MISSED";
    let reason = `زمان ${slot.time} تهران گذشته اما هیچ شروعی برای این Slot ثبت نشده است؛ Cron/Scheduler یا مسیر اجرای Slot باید بررسی شود.`;
    if (existing?.status === "STARTED") {
      status = "FAILED";
      code = "EXECUTION_INCOMPLETE";
      reason = `Cron برای Slot ساعت ${slot.time} شروع ثبت کرده، اما تا ${DELIVERY_HEALTH_GRACE_MINUTES} دقیقه بعد نتیجه نهایی SENT/SKIPPED/FAILED ثبت نشده است.`;
    }
    const event = await recordDeliveryHealthEvent(env, {
      slotId: slot.id, now, date, status, phase: "DELIVERY_WATCHDOG", code, reason,
      expectedChannel: await scheduledPublicationChannel(env)
    });
    if (event) alerts.push(event);
  }
  for (const event of alerts) {
    await notifyAdmin(env, [
      `🚨 <b>${event.status === "MISSED" ? "پست زمان‌بندی‌شده اجرا نشد" : "اجرای پست نیمه‌کاره ماند"}</b>`,
      "",
      `پست: <b>${esc(event.label)}</b>`,
      `زمان برنامه: <code>${esc(event.scheduledTime)}</code>`,
      `وضعیت: <code>${esc(event.status)}</code>`,
      `کد: <code>${esc(event.code)}</code>`,
      `علت: ${esc(event.reason)}`
    ].join("\n"));
  }
  return alerts;
}
