  const heartbeatState = heartbeatAgeMinutes === null ? "❌ بدون Heartbeat" : heartbeatAgeMinutes <= 12 ? `✅ ${esc(scheduler.heartbeat.tehranTime || "—")} تهران · ${heartbeatAgeMinutes} دقیقه قبل` : `🚨 آخرین Heartbeat ${heartbeatAgeMinutes} دقیقه قبل`;
