    if (state.rootReason) detail.push(`ریشه: ${esc(state.rootReason)}`);
    if (state.code) detail.push(`کد: <code>${esc(state.code)}</code>`);
    if (state.rootCode && state.rootCode !== state.code) detail.push(`کد ریشه: <code>${esc(state.rootCode)}</code>`);
    if (state.baleMessageId) detail.push(`Message ID: <code>${esc(state.baleMessageId)}</code>`);
