  const destination = /^[A-Z]{3}(?:ALL)?$/.test(String(candidate?.bookingDestination || "")) ? candidate.bookingDestination : candidate.destination;
  return `https://flyyab.ir/international-flights/${origin}-${destination}?adult=1&child=0&infant=0&departing=${candidate.departureDate}`;
