async function internationalRadarControl(env, path, init = {}) {
  if (!env.BOT_CONTROL) throw new Error("BOT_CONTROL برای رادار خارجی متصل نیست");
  const stub = flyyabControlStub(env, "radar-international");
  const response = await stub.fetch(`https://bot-control${path}`, init);
  const data = await response.json().catch(() => ({}));
  if (!response.ok || data?.ok === false) {
    const error = new Error(data?.error || `International Radar control ${response.status}`);
    error.status = response.status;
    error.data = data;
    throw error;
  }
  return data;
}
