async function runInternationalRadarCycle(env, now = new Date()) {
  try {
    const data = await fetchFlightPrices();
    const snapshot = buildInternationalRadarSnapshot(data, radarCurrentJalali(now));
    let remaining = snapshot.candidates.slice(0, 80);
    let lastResult = null;
    for (let attempt = 0; attempt < INTERNATIONAL_RADAR_RULES.verificationAttemptsPerScan; attempt++) {
      const result = await internationalRadarControl(env, "/international-radar/ingest", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({
          scanId: internationalRadarScanId(now, attempt),
          observedAtMs: now.getTime() + attempt,
          tehranClock: clock(now),
          currentJalali: snapshot.currentJalali,
          sourceCounts: snapshot.counts,
          candidates: remaining
        })
      });
      lastResult = result;
      if (result?.warning) {
        await notifyAdmin(env, `⚠️ <b>رادار پرواز خارجی — افت پوشش منبع</b>\n\n<code>${esc(result.warning)}</code>\nمسیرهای بازار آسیب‌دیده از انتخاب حذف شدند و هیچ اعلان مشکوکی منتشر نشد.`);
      }
      const reservation = result?.reservation;
      if (!reservation?.candidate) return result;
      const verificationNow = new Date();
      const verification = await verifyInternationalRadarCandidate(reservation.candidate, verificationNow);
      if (!verification.ok) {
        await internationalRadarAck(env, {
          token: reservation.token,
          status: "verification_rejected",
          atMs: verificationNow.getTime(),
          candidate: reservation.candidate,
          reason: verification.reason,
          detail: verification.detail || null
        });
        remaining = remaining.filter(candidate => candidate.key !== reservation.candidate.key);
        continue;
      }
      const candidate = await internationalRadarAttachBookingRoute(verification.candidate);
      const botMode = await getBotMode(env);
      const radarMode = reservation.radarMode === "live" ? "live" : "test";
      const liveAllowed = radarMode === "live" && botMode === "live";
      const channel = liveAllowed ? productionChannel(env) : testChannel(env);
      try {
        const sent = await sendInternationalRadarBale(env, channel, candidate);
        await internationalRadarAck(env, {
          token: reservation.token,
          status: "published",
          atMs: Date.now(),
          channel,
          baleMessageId: sent?.result?.message_id || null,
          candidate
        });
        return { ...result, sent: true, channel, candidate };
      } catch (error) {
        const status = error?.internationalRadarSendExplicit ? "send_failed" : "send_unknown";
        try {
          await internationalRadarAck(env, { token: reservation.token, status, atMs: Date.now(), channel, error: error.message, candidate });
        } catch {}
        await notifyAdmin(env, status === "send_unknown"
          ? `⚠️ <b>رادار خارجی — وضعیت ارسال نامشخص</b>\n\nمسیر: ${esc(candidate.origin)} به ${esc(candidate.destination)}\nعلت: ${esc(error.message)}\nبرای جلوگیری از پیام تکراری، ارسال خودکار دوباره انجام نشد.`
          : `❌ <b>رادار خارجی ارسال نشد</b>\n\nعلت: ${esc(error.message)}`);
        return { ...result, sent: false, sendStatus: status, error: error.message };
      }
    }
    return lastResult || { ok: true, sent: false, reason: "NO_VERIFIED_CANDIDATE" };
  } catch (error) {
    const report = await internationalRadarReportFailure(env, error);
    if (report?.notify) await notifyAdmin(env, `❌ <b>رادار پرواز خارجی — پایش ناموفق بود</b>\n\nعلت اصلی: ${esc(error.message)}\nهیچ اعلان عمومی ارسال نشد.`);
    console.error("FlyYab International Radar cycle error", error);
    return { ok: false, error: error.message };
  }
}
function internationalRadarDurationText(ms) {
  const totalMinutes = Math.max(0, Math.ceil(Number(ms || 0) / 6e4));
  const days = Math.floor(totalMinutes / 1440);
  const hours = Math.floor(totalMinutes % 1440 / 60);
  const minutes = totalMinutes % 60;
  return `${days ? `${days} روز و ` : ""}${hours} ساعت و ${minutes} دقیقه`;
}
