  if (NIGHT_LITE_BAD_IMAGE.test(haystack)) return null;
  const width = Number(info.width || 0), height = Number(info.height || 0);
  if (!width || !height) return null;
  const ratio = width / height;
  if (width < 800 || height < 500 || ratio < 0.85 || ratio > 2.5) return null;
  const strict = width >= 1000 && height >= 600 && ratio >= 1.05;
  let score = strict ? 50 : 20;
  const normalizedTitle = normalizeDestinationText(title);
  const queryTokens = normalizeDestinationText(candidate.query).split(/\s+/).filter((token) => token.length > 2);
