    id: `commons:${page.pageid || title}`,
    url: info.thumburl || info.url,
    originalUrl: info.url,
    page: nightCommonsPageUrl(page.title),
    source: "Wikimedia Commons",
    width,
    height,
    score,
    fileName: title,
    author: nightPlainText(meta.Artist?.value || meta.Credit?.value || "Wikimedia Commons"),
    license: nightPlainText(meta.LicenseShortName?.value || meta.UsageTerms?.value || ""),
    licenseUrl: String(meta.LicenseUrl?.value || "")
