const NIGHT_DESTINATION_CAPTION_LIMIT = 1024;
const NIGHT_DESTINATION_EDITORIAL_CEILING = 1024;
const NIGHT_DESTINATION_EDITORIAL_FLOOR = 120;
function baleHtmlText(html = "") { return String(html).replace(/<[^>]+>/g, "").replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'").replace(/&amp;/g, "&"); }
function nightPackageCaption(pkg) {
  if (!pkg?.displayName && !pkg?.entity?.labelFa) throw new Error("نام مقصد برای کپشن کامل نیست");
  if (!pkg?.editorial?.body) throw new Error("متن کوتاه مقصد آماده نیست");
  if (!Array.isArray(pkg?.images) || pkg.images.length < 1 || pkg.images.length > 10) throw new Error("پست مقصد باید بین ۱ تا ۱۰ تصویر تأییدشده داشته باشد");
  for (const image of pkg.images) if (!image?.url || !/^https:\/\//i.test(String(image.url))) throw new Error("یکی از تصاویر آلبوم URL معتبر ندارد");
  const caption = nightPackageText(pkg); const visible = baleHtmlText(caption); const visibleLength = [...visible].length;
  if (visibleLength < NIGHT_DESTINATION_EDITORIAL_FLOOR) throw new Error(`کپشن مقصد فقط ${visibleLength} نویسه دارد`);
  if (visibleLength > NIGHT_DESTINATION_EDITORIAL_CEILING) throw new Error(`کپشن مقصد ${visibleLength} نویسه دارد و از سقف داخلی ${NIGHT_DESTINATION_EDITORIAL_CEILING} بیشتر است`);
  if (visibleLength > NIGHT_DESTINATION_CAPTION_LIMIT) throw new Error(`کپشن مقصد از سقف بله بیشتر است`);
  return caption;
}

