  const existing = state.preparedPackage;
  if (!fresh && !preferredName && existing?.version === NIGHT_DESTINATION_VERSION && existing?.catalogRevision === NIGHT_DESTINATION_CATALOG_REVISION && existing?.date === date && ["READY", "LOCKED"].includes(existing?.status)) return existing;
