      ...state,
      version: 6,
      preparedPackage: validExisting,
      selectionAudit: { at: new Date().toISOString(), status: "FAILED", attempts: error.attempts || [] },
      lastReport: { ok: false, status: "SKIPPED", at: new Date().toISOString(), date, error: error.message, code: error.code || "ERROR", attempts: error.attempts || [], previousPackagePreserved: Boolean(validExisting) }
