    version: 6,
    preparedPackage: locked,
    plans,
    lastReport: { ok: true, status: "LOCKED", at: locked.lockedAt, date, destination: locked.displayName, images: locked.images.length, imageSources: locked.imageDiagnostics?.sources || [], catalogId: locked.catalogId }
