    const delta = deliveryRecoveryDeltaMinutes(nowTime, slot.time);
    if (delta !== 5 && delta !== 10) continue;
    const current = record.slots?.[slot.id] || null;
    if (current && ["SENT", "SKIPPED"].includes(current.status)) continue;
    const retryAttempt = delta === 5 ? 1 : 2;
    if (Number(current?.retryAttempt || 0) >= retryAttempt) continue;
