function freeTierJobKey(job, scheduledNow = new Date()) {
  return `${currentTehranIso(scheduledNow)}|${clock(scheduledNow)}|${String(job?.instance || job?.name || job?.action || "job")}|${String(job?.name || job?.action || "job")}`;
}
function nextCoordinatorAlarmMs(nowMs = Date.now()) {
  const step = 5 * 60 * 1000;
  return (Math.floor(Number(nowMs) / step) + 1) * step + 5000;
}
async function dispatchIndependentJob(env, job, scheduledNow = new Date()) {
  if (!env.FREE_TIER_EXECUTOR) throw new Error("FREE_TIER_EXECUTOR_BINDING_MISSING");
  const id = env.FREE_TIER_EXECUTOR.idFromName(`flyyab-bale-${job.instance || job.name}-v1`);
  const stub = env.FREE_TIER_EXECUTOR.get(id);
  const response = await stub.fetch("https://free-tier-executor/job", {
    method:"POST",
    headers:{"content-type":"application/json"},
    body:JSON.stringify({ job, jobKey:freeTierJobKey(job, scheduledNow), scheduledTime:scheduledNow.toISOString(), buildId:FLYYAB_BUILD_ID })
  });
  if (!response.ok) {
    const detail = await response.text().catch(()=>"");
    throw new Error(`INDEPENDENT_JOB_${job.name}_${response.status}:${detail.slice(0,180)}`);
  }
  return response.json().catch(()=>({ok:true,job:job.name}));
}
async function runCoordinatorDispatch(env, scheduledNow = new Date()) {
  const jobs = independentJobsForTick(scheduledNow);
  const settled = await Promise.allSettled(jobs.map((job)=>dispatchIndependentJob(env, job, scheduledNow)));
  const failed = settled.map((item,index)=>({item,job:jobs[index]})).filter(x=>x.item.status==="rejected");
  if (failed.length) {
    const summary = failed.map(x=>`${x.job.name}:${String(x.item.reason?.message||x.item.reason).slice(0,120)}`).join(" | ");
    throw new Error(`COORDINATOR_JOB_DISPATCH_FAILURE:${summary}`);
  }
  return { ok:true, engine:FREE_TIER_DELIVERY_VERSION, buildId:FLYYAB_BUILD_ID, tehranTime:clock(scheduledNow), jobs:jobs.map((job,index)=>({name:job.name,action:job.action,instance:job.instance,status:settled[index].status})) };
}
async function dispatchFreeTierSchedulerTick(env, scheduledNow = new Date()) {
  if (!baleAutomationEnabled(env)) return Response.json({ ok:true, disabled:true, reason:"BALE_AUTOMATION_DISABLED" });
  if (!env.FREE_TIER_EXECUTOR) throw new Error("FREE_TIER_EXECUTOR_BINDING_MISSING");
  const id = env.FREE_TIER_EXECUTOR.idFromName("flyyab-bale-coordinator-v1");
  const stub = env.FREE_TIER_EXECUTOR.get(id);
  const response = await stub.fetch("https://free-tier-executor/tick", {
    method:"POST",
    headers:{"content-type":"application/json"},
    body:JSON.stringify({ scheduledTime:scheduledNow.toISOString(), buildId:FLYYAB_BUILD_ID, source:"CRON" })
  });
  if (!response.ok) {
    const detail = await response.text().catch(()=>"");
    throw new Error(`FREE_TIER_COORDINATOR_${response.status}:${detail.slice(0,240)}`);
  }
  return response;
}
async function bootstrapFreeTierCoordinator(env) {
  if (!baleAutomationEnabled(env)) return { ok:true, disabled:true, reason:"BALE_AUTOMATION_DISABLED" };
  if (!env.FREE_TIER_EXECUTOR) return { ok:false, reason:"FREE_TIER_EXECUTOR_BINDING_MISSING" };
  const id = env.FREE_TIER_EXECUTOR.idFromName("flyyab-bale-coordinator-v1");
  const response = await env.FREE_TIER_EXECUTOR.get(id).fetch("https://free-tier-executor/bootstrap", { method:"POST" });
  if (!response.ok) throw new Error(`FREE_TIER_COORDINATOR_BOOTSTRAP_${response.status}`);
  return response.json().catch(()=>({ok:true}));
}
var FreeTierExecutor = class {
  constructor(state, env) { this.state = state; this.env = env; }
  async storageGet(key) { return this.state?.storage?.get ? this.state.storage.get(key) : undefined; }
  async storagePut(key, value) { if (this.state?.storage?.put) await this.state.storage.put(key, value); }
  async storageDelete(key) { if (this.state?.storage?.delete) await this.state.storage.delete(key); }
  async storageList(prefix = "") { return this.state?.storage?.list ? this.state.storage.list({ prefix }) : new Map(); }
  async setAlarmAt(ms) { if (this.state?.storage?.setAlarm) await this.state.storage.setAlarm(Number(ms)); }
  async getAlarmAt() { return this.state?.storage?.getAlarm ? this.state.storage.getAlarm() : null; }
  async deleteAlarm() { if (this.state?.storage?.deleteAlarm) await this.state.storage.deleteAlarm(); }
  retryKey(jobKey) { return `retry:pending:${jobKey}`; }
  async scheduleNextJobRetryAlarm() {
    const pending = await this.storageList("retry:pending:");
    let earliest = Infinity;
    for (const value of pending.values()) {
      const at = Number(value?.nextAttemptAtMs || 0);
      if (at > 0 && at < earliest) earliest = at;
    }
    if (!Number.isFinite(earliest)) { await this.deleteAlarm(); return null; }
    const target = Math.max(Date.now() + 1000, earliest);
    await this.setAlarmAt(target);
    return target;
  }
  async scheduleCoordinatorAlarm() {
    const at = nextCoordinatorAlarmMs(Date.now());
    await this.storagePut("coordinator:enabled", { enabled:true, buildId:FLYYAB_BUILD_ID, nextAlarmAt:new Date(at).toISOString(), updatedAt:new Date().toISOString() });
    await this.setAlarmAt(at);
    return at;
  }
  async runCoordinatorTick(scheduledNow = new Date(), source = "ALARM") {
    if (!baleAutomationEnabled(this.env)) {
      await this.storagePut("coordinator:enabled", { enabled:false, buildId:FLYYAB_BUILD_ID, disabledAt:new Date().toISOString() });
      await this.deleteAlarm();
      return { ok:true, disabled:true, reason:"BALE_AUTOMATION_DISABLED", source };
    }
    await this.scheduleCoordinatorAlarm();
    const minute = Number(clock(scheduledNow).slice(3,5));
    if (!Number.isInteger(minute) || minute % 5 !== 0) return { ok:true, idle:true, reason:"NOT_FIVE_MINUTE_BOUNDARY", source, tehranTime:clock(scheduledNow) };
    const tickKey = `${currentTehranIso(scheduledNow)}|${clock(scheduledNow)}`;
    const last = await this.storageGet("coordinator:last-tick");
    if (last?.tickKey === tickKey && last?.buildId === FLYYAB_BUILD_ID && last?.status === "DONE") {
      return { ok:true, deduped:true, tickKey, source, tehranTime:clock(scheduledNow) };
    }
    await this.storagePut("coordinator:current-tick", { tickKey, status:"DISPATCHING", source, startedAt:new Date().toISOString(), buildId:FLYYAB_BUILD_ID });
    const result = await runCoordinatorDispatch(this.env, scheduledNow);
    const completed = { tickKey, status:"DONE", source, completedAt:new Date().toISOString(), buildId:FLYYAB_BUILD_ID, jobCount:result.jobs?.length || 0 };
    await this.storagePut("coordinator:last-tick", completed);
    await this.storageDelete("coordinator:current-tick");
    return { ...result, tickKey, source };
  }
  async publicSlotRetryAllowed(job, scheduledNow) {
    const slotId = String(job?.args?.slotId || "");
    if (!slotId) return false;
    const record = await getDailyDeliveryHealth(withFlyYabExecutionScope(this.env,"production"), currentTehranIso(scheduledNow));
    const current = record?.slots?.[slotId] || null;
    if (!current) return true;
    if (["SENT","SKIPPED"].includes(current.status)) return false;
    if (String(current.phase || "") === "BALE_SENDING" && current.safeToRetry !== true) return false;
    return current.safeToRetry === true || DELIVERY_SAFE_RETRY_PHASES.has(String(current.phase || ""));
  }
  async runJobEnvelope(body, { fromAlarm = false } = {}) {
    const scheduledNow = new Date(String(body?.scheduledTime || ""));
    const job = body?.job || null;
    const jobKey = String(body?.jobKey || (job?.action && Number.isFinite(scheduledNow.getTime()) ? freeTierJobKey(job, scheduledNow) : ""));
    if (!job?.action || !jobKey || !Number.isFinite(scheduledNow.getTime())) throw new Error("FREE_TIER_BAD_JOB");
    const ledgerKey = `job-ledger:${jobKey}`;
    const retryKey = this.retryKey(jobKey);
    const existing = await this.storageGet(ledgerKey);
    if (existing?.status === "DONE" && existing?.buildId === FLYYAB_BUILD_ID) return { ok:true, deduped:true, job:job.name, action:job.action, jobKey };
    if (existing?.status === "RUNNING" && !fromAlarm && Date.now() - Number(existing.startedAtMs || 0) < 120000) return { ok:true, deduped:true, running:true, job:job.name, action:job.action, jobKey };
    // For a retry of a public publication, consult Delivery Health BEFORE any
    // Bale code is entered. A runtime may have died after Bale accepted
    // the message but before our response arrived; that state is intentionally
    // non-retryable to prevent a duplicate public post.
    if (job.action === "public_slot" && existing && Number(existing.attempt || 0) > 0) {
      const allowed = await this.publicSlotRetryAllowed(job, scheduledNow);
      if (!allowed) {
        const blocked = { ...existing, status:"BLOCKED_AMBIGUOUS", blockedAt:new Date().toISOString(), buildId:FLYYAB_BUILD_ID, reason:"PUBLIC_SLOT_RETRY_NOT_SAFE" };
        await this.storagePut(ledgerKey, blocked);
        await this.storageDelete(retryKey);
        await this.scheduleNextJobRetryAlarm();
        return { ok:false, blocked:true, ambiguous:true, job:job.name, action:job.action, jobKey, reason:"PUBLIC_SLOT_RETRY_NOT_SAFE" };
      }
    }
    const attempt = Math.max(1, Number(existing?.attempt || 0) + 1);
    const effectiveJob = job.action === "public_slot"
      ? { ...job, args:{ ...(job.args||{}), retryAttempt:Math.max(Number(job.args?.retryAttempt||0), attempt-1) } }
      : job;
    const running = { jobKey, job:effectiveJob, scheduledTime:scheduledNow.toISOString(), status:"RUNNING", attempt, startedAt:new Date().toISOString(), startedAtMs:Date.now(), buildId:FLYYAB_BUILD_ID };
    await this.storagePut(ledgerKey, running);
    // Crash watchdog is persisted before real work starts. If the invocation is
    // terminated by the runtime, this per-job record survives and the DO alarm
    // can resume it without losing another failed job on the same engine.
    await this.storagePut(retryKey, { ...running, nextAttemptAtMs:Date.now()+120000, retryReason:"IN_FLIGHT_WATCHDOG" });
    await this.scheduleNextJobRetryAlarm();
    try {
      const result = await runIndependentJob(this.env, effectiveJob, scheduledNow);
      if (effectiveJob.action === "public_slot") {
        const delivery = await getDailyDeliveryHealth(withFlyYabExecutionScope(this.env,"production"), currentTehranIso(scheduledNow));
        const status = delivery?.slots?.[String(effectiveJob?.args?.slotId || "")]?.status || "";
        if (!["SENT","SKIPPED"].includes(status)) throw new Error(`PUBLIC_SLOT_NOT_TERMINAL:${effectiveJob?.args?.slotId || "UNKNOWN"}:${status || "MISSING"}`);
      }
      await this.storagePut(ledgerKey, { ...running, status:"DONE", completedAt:new Date().toISOString(), resultType:String(result?.status||result?.phase||result?.action||"OK") });
      await this.storageDelete(retryKey);
      await this.scheduleNextJobRetryAlarm();
      return { ok:true, job:effectiveJob.name, action:effectiveJob.action, jobKey, attempt, resultType:String(result?.status||result?.phase||result?.action||"OK") };
    } catch (error) {
      const failed = { ...running, status:"FAILED", failedAt:new Date().toISOString(), error:String(error?.message||error).slice(0,500) };
      await this.storagePut(ledgerKey, failed);
      let retryable = attempt < 4;
      if (effectiveJob.action === "public_slot") retryable = retryable && await this.publicSlotRetryAllowed(effectiveJob, scheduledNow);
      if (retryable) {
        const nextAttemptAtMs = Date.now() + Math.min(5*60*1000, 60000 * attempt);
        await this.storagePut(retryKey, { ...failed, nextAttemptAtMs, retryReason:"JOB_FAILED" });
      } else {
        await this.storageDelete(retryKey);
      }
      await this.scheduleNextJobRetryAlarm();
      throw error;
    }
  }

  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname === "/bootstrap" && request.method === "POST") {
      if (!baleAutomationEnabled(this.env)) {
        await this.storagePut("coordinator:enabled", { enabled:false, buildId:FLYYAB_BUILD_ID, disabledAt:new Date().toISOString() });
        await this.deleteAlarm();
        return Response.json({ok:true,disabled:true,reason:"BALE_AUTOMATION_DISABLED",engine:FREE_TIER_DELIVERY_VERSION,buildId:FLYYAB_BUILD_ID});
      }
      const existing = await this.storageGet("coordinator:enabled");
      const existingAlarm = await this.getAlarmAt();
      if (existing?.enabled && existing?.buildId === FLYYAB_BUILD_ID && Number(existingAlarm || 0) > Date.now()) {
        return Response.json({ok:true,deduped:true,engine:FREE_TIER_DELIVERY_VERSION,buildId:FLYYAB_BUILD_ID,nextAlarmAt:new Date(Number(existingAlarm)).toISOString()});
      }
      const at = await this.scheduleCoordinatorAlarm();
      return Response.json({ok:true,engine:FREE_TIER_DELIVERY_VERSION,buildId:FLYYAB_BUILD_ID,nextAlarmAt:new Date(at).toISOString()});
    }
    if (url.pathname === "/tick" && request.method === "POST") {
      const body = await request.json().catch(()=>({}));
      const scheduledNow = new Date(String(body?.scheduledTime || ""));
      if (!Number.isFinite(scheduledNow.getTime())) return Response.json({ok:false,error:"bad scheduled time"},{status:400});
      try { return Response.json(await this.runCoordinatorTick(scheduledNow, String(body?.source || "CRON"))); }
      catch (error) { console.error("COORDINATOR_TICK_FAILED",clock(scheduledNow),error); return Response.json({ok:false,error:String(error?.message||error).slice(0,500)},{status:500}); }
    }
    if (url.pathname === "/job" && request.method === "POST") {
      const body = await request.json().catch(()=>({}));
      try { return Response.json(await this.runJobEnvelope(body)); }
      catch (error) {
        console.error("INDEPENDENT_JOB_FAILED", body?.job?.name, body?.scheduledTime, error);
        return Response.json({ok:false,job:body?.job?.name,action:body?.job?.action,engine:FREE_TIER_DELIVERY_VERSION,buildId:FLYYAB_BUILD_ID,error:String(error?.message||error).slice(0,500)},{status:500});
      }
    }
    return Response.json({ok:false,error:"not found"},{status:404});
  }
  async alarm() {
    if (!baleAutomationEnabled(this.env)) {
      await this.storagePut("coordinator:enabled", { enabled:false, buildId:FLYYAB_BUILD_ID, disabledAt:new Date().toISOString() });
      await this.deleteAlarm();
      return;
    }
    const coordinator = await this.storageGet("coordinator:enabled");
    if (coordinator?.enabled) {
      try { await this.runCoordinatorTick(new Date(), "ALARM"); }
      catch (error) { await this.scheduleCoordinatorAlarm(); throw error; }
      return;
    }
    const pendingMap = await this.storageList("retry:pending:");
    const pending = [...pendingMap.values()].filter((x)=>x?.job&&x?.scheduledTime).sort((a,b)=>Number(a.nextAttemptAtMs||0)-Number(b.nextAttemptAtMs||0));
    if (!pending.length) { await this.deleteAlarm(); return; }
    const next = pending[0];
    if (Number(next.nextAttemptAtMs||0) > Date.now()+250) { await this.setAlarmAt(Number(next.nextAttemptAtMs)); return; }
    try { await this.runJobEnvelope(next, { fromAlarm:true }); }
    catch (error) {
      // runJobEnvelope already persisted retry policy. Keep the alarm alive for
      // any remaining job instead of letting one failure erase sibling retries.
      const latest = await this.storageList("retry:pending:");
      if (latest.size) { await this.scheduleNextJobRetryAlarm(); return; }
      throw error;
    }
    await this.scheduleNextJobRetryAlarm();
  }
};

var BotControl = class {
  constructor(state) {
    this.state = state;
  }
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname.startsWith("/international-radar/")) return internationalRadarDurableFetch(this.state.storage, request);
    if (url.pathname.startsWith("/radar/")) return radarDurableFetch(this.state.storage, request);
    if (url.pathname === "/weather/lease") {
      const key = "weather-scan-lease-v1";
      if (request.method === "POST") {
        const body = await request.json().catch(() => ({}));
        const owner = String(body.owner || "");
        const ttlMs = Math.max(10000, Math.min(180000, Number(body.ttlMs) || WEATHER_SCAN_LEASE_MS));
        if (!owner) return Response.json({ acquired: false, reason: "OWNER_REQUIRED" }, { status: 400 });
        const current = await this.state.storage.get(key);
        const now = Date.now();
        if (current?.owner && current.owner !== owner && Number(current.expiresAt || 0) > now) return Response.json({ acquired: false, owner: current.owner, expiresAt: current.expiresAt });
        const lease = { owner, expiresAt: now + ttlMs };
        await this.state.storage.put(key, lease);
        return Response.json({ acquired: true, ...lease });
      }
      if (request.method === "DELETE") {
        const body = await request.json().catch(() => ({}));
        const current = await this.state.storage.get(key);
        if (!current || !body.owner || current.owner === body.owner) await this.state.storage.delete(key);
        return Response.json({ ok: true });
      }
      return Response.json({ acquired: false }, { status: 405 });
    }
    if (url.pathname === "/weather/state") {
      const key = "weather-state-v1";
      if (request.method === "POST") { const state = await request.json(); await this.state.storage.put(key, state); return Response.json({ ok: true }); }
      const state = await this.state.storage.get(key); return Response.json({ ok: true, state: state || weatherDefaultState() });
    }
    if (url.pathname === "/night-destination/state") {
      if (request.method === "POST") {
        const state = await request.json();
        await this.state.storage.put("night-destination-state-v2", state);
        return Response.json({ ok: true });
      }
      const state = await this.state.storage.get("night-destination-state-v2");
      return Response.json({ ok: true, state: state || nightDestinationDefaultState() });
    }
    if (url.pathname === "/heritage/state") {
      if (request.method === "POST") {
        const state = await request.json();
        await this.state.storage.put("heritage-state-v1", state);
        return Response.json({ ok: true });
      }
      const state = await this.state.storage.get("heritage-state-v1");
      return Response.json({ ok: true, state: state || heritageDefaultState() });
    }
    if (url.pathname.startsWith("/heritage/record/")) {
      const day = Number(url.pathname.split("/").pop());
      if (!Number.isInteger(day) || day < 1 || day > 365) return Response.json({ ok: false }, { status: 400 });
      const key = `heritage-record-${day}`;
      if (request.method === "POST") {
        const record = await request.json();
        await this.state.storage.put(key, record);
        return Response.json({ ok: true });
      }
      const record = await this.state.storage.get(key);
      return record ? Response.json({ ok: true, record }) : Response.json({ ok: false }, { status: 404 });
    }

    if (url.pathname.startsWith("/free-tier/package/")) {
      const parts = url.pathname.split("/").filter(Boolean);
      const date = decodeURIComponent(parts[2] || "");
      const slotId = decodeURIComponent(parts[3] || "");
      if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || !deliverySlotDefinition(slotId)) return Response.json({ ok: false, error: "bad free-tier package key" }, { status: 400 });
      const key = `free-tier-package-v1-${date}-${slotId}`;
      if (request.method === "POST") {
        const packageRecord = await request.json();
        await this.state.storage.put(key, packageRecord);
        return Response.json({ ok: true, package: packageRecord });
      }
      if (request.method === "DELETE") {
        await this.state.storage.delete(key);
        return Response.json({ ok: true });
      }
      const packageRecord = await this.state.storage.get(key);
      return packageRecord ? Response.json({ ok: true, package: packageRecord }) : Response.json({ ok: false }, { status: 404 });
    }

    if (url.pathname.startsWith("/morning/record/")) {
      const date = decodeURIComponent(url.pathname.split("/").pop() || "");
      if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return Response.json({ ok: false, error: "bad date" }, { status: 400 });
      const key = `morning-record-v2-${date}`;
      if (request.method === "POST") {
        const record = await request.json();
        await this.state.storage.put(key, record);
        await this.state.storage.put("morning-last-date-v2", date);
        return Response.json({ ok: true });
      }
      const record = await this.state.storage.get(key);
      return record ? Response.json({ ok: true, record }) : Response.json({ ok: false }, { status: 404 });
    }


    if (url.pathname === "/delivery/activation") {
      const activationKey = "delivery-health-activation-v1";
      if (request.method === "POST") {
        const incoming = await request.json();
        if (!incoming?.tehranDate || !incoming?.tehranTime || !incoming?.buildId) {
          return Response.json({ ok: false, error: "bad activation" }, { status: 400 });
        }
        let activation = await this.state.storage.get(activationKey);
        // Start a fresh monitoring window for a new build/version; otherwise keep the original activation moment.
        if (!activation || activation.buildId !== incoming.buildId || activation.version !== incoming.version) {
          activation = incoming;
          await this.state.storage.put(activationKey, activation);
        }
        return Response.json({ ok: true, activation });
      }
      const activation = await this.state.storage.get(activationKey) || null;
      return Response.json({ ok: true, activation });
    }

    if (url.pathname === "/delivery/heartbeat") {
      const heartbeatKey = "delivery-heartbeat-v1";
      const activationKey = "delivery-health-activation-v1";
      if (request.method === "POST") {
        const heartbeat = await request.json();
        if (!heartbeat?.scheduledAt || !heartbeat?.tehranDate || !heartbeat?.tehranTime) return Response.json({ ok: false, error: "bad heartbeat" }, { status: 400 });
        await this.state.storage.put(heartbeatKey, heartbeat);
        let activation = await this.state.storage.get(activationKey);
        if (!activation || activation.buildId !== (heartbeat.buildId || "") || activation.version !== (heartbeat.version || DELIVERY_HEALTH_VERSION)) {
          activation = {
            version: heartbeat.version || DELIVERY_HEALTH_VERSION,
            activatedAt: heartbeat.receivedAt || new Date().toISOString(),
            tehranDate: heartbeat.tehranDate,
            tehranTime: heartbeat.tehranTime,
            buildId: heartbeat.buildId || ""
          };
          await this.state.storage.put(activationKey, activation);
        }
        return Response.json({ ok: true, heartbeat, activation });
      }
      const heartbeat = await this.state.storage.get(heartbeatKey) || null;
      const activation = await this.state.storage.get(activationKey) || null;
      return Response.json({ ok: true, heartbeat, activation });
    }

    if (url.pathname === "/delivery/health/event" && request.method === "POST") {
      const event = await request.json();
      if (!/^\d{4}-\d{2}-\d{2}$/.test(String(event?.date || "")) || !deliverySlotDefinition(event?.slotId) || !event?.status) {
        return Response.json({ ok: false, error: "bad delivery health event" }, { status: 400 });
      }
      const key = `delivery-health-v1-${event.date}`;
      const previous = await this.state.storage.get(key) || { version: DELIVERY_HEALTH_VERSION, date: event.date, slots: {}, updatedAt: null, summarySentAt: null };
      const current = previous.slots?.[event.slotId] || null;
      // A terminal result is immutable against a late STARTED event from the same Cron tick.
      const isRecoveryStart = event.status === "STARTED" && /^RECOVERY_/i.test(String(event.phase || ""));
      const shouldKeepCurrent = current && DELIVERY_TERMINAL_STATUSES.has(current.status) && event.status === "STARTED" && !isRecoveryStart;
      const chosen = shouldKeepCurrent ? current : { ...(current || {}), ...event };
      const record = {
        ...previous,
        version: DELIVERY_HEALTH_VERSION,
        date: event.date,
        slots: { ...(previous.slots || {}), [event.slotId]: chosen },
        updatedAt: new Date().toISOString()
      };
      await this.state.storage.put(key, record);
      return Response.json({ ok: true, event: chosen, record });
    }

    if (url.pathname.startsWith("/delivery/health/") && request.method === "GET") {
      const date = decodeURIComponent(url.pathname.split("/").pop() || "");
      if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return Response.json({ ok: false, error: "bad date" }, { status: 400 });
      const record = await this.state.storage.get(`delivery-health-v1-${date}`);
      return record ? Response.json({ ok: true, record }) : Response.json({ ok: false }, { status: 404 });
    }

    if (url.pathname === "/delivery/health/summary" && request.method === "POST") {
      const body = await request.json();
      const date = String(body?.date || "");
      if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return Response.json({ ok: false, error: "bad date" }, { status: 400 });
      const key = `delivery-health-v1-${date}`;
      const previous = await this.state.storage.get(key) || { version: DELIVERY_HEALTH_VERSION, date, slots: {}, updatedAt: null };
      const record = { ...previous, summarySentAt: body.sentAt || new Date().toISOString(), summaryMessageId: body.messageId ?? null, updatedAt: new Date().toISOString() };
      await this.state.storage.put(key, record);
      return Response.json({ ok: true, record });
    }

    if (url.pathname === "/delivery/incidents") {
      const key = "delivery-incidents-v1";
      if (request.method === "POST") {
        const incident = await request.json();
        if (!incident?.id || !incident?.postType || !incident?.date || !incident?.primaryReason) {
          return Response.json({ ok: false, error: "bad incident" }, { status: 400 });
        }
        const previous = await this.state.storage.get(key) || [];
        const incidents = [incident, ...previous.filter((item) => item?.id !== incident.id)].slice(0, 200);
        await this.state.storage.put(key, incidents);
        await this.state.storage.put(`delivery-last-${incident.postType}`, incident);
        return Response.json({ ok: true, incident });
      }
      const postType = String(url.searchParams.get("postType") || "");
      const date = String(url.searchParams.get("date") || "");
      const limit = Math.max(1, Math.min(30, Number(url.searchParams.get("limit")) || 10));
      const previous = await this.state.storage.get(key) || [];
      const incidents = previous
        .filter((item) => (!postType || item?.postType === postType) && (!date || item?.date === date))
        .slice(0, limit);
      return Response.json({ ok: true, incidents });
    }

    if (url.pathname.startsWith("/occasion/record/")) {
      const date = decodeURIComponent(url.pathname.split("/").pop() || "");
      if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return Response.json({ ok: false, error: "bad date" }, { status: 400 });
      const key = `occasion-record-v2-${date}`;
      if (request.method === "POST") {
        const record = await request.json();
        await this.state.storage.put(key, record);
        await this.state.storage.put("occasion-last-date-v2", date);
        return Response.json({ ok: true });
      }
      const record = await this.state.storage.get(key);
      return record ? Response.json({ ok: true, record }) : Response.json({ ok: false }, { status: 404 });
    }

    if (url.pathname.startsWith("/media/override/")) {
      const type = String(url.pathname.split("/").pop() || "").toLowerCase();
      if (!MANAGED_POST_MEDIA[type]) return Response.json({ ok: false, error: "bad media type" }, { status: 400 });
      const key = `managed-media-override-v1-${type}`;
      if (request.method === "POST") {
        const override = await request.json().catch(() => null);
        if (!override?.fileId || override.type !== type || !/^image\//.test(String(override.mimeType || ""))) {
          return Response.json({ ok: false, error: "bad media override" }, { status: 400 });
        }
        await this.state.storage.put(key, override);
        return Response.json({ ok: true, override });
      }
      if (request.method === "DELETE") {
        await this.state.storage.delete(key);
        return Response.json({ ok: true, override: null });
      }
      const override = await this.state.storage.get(key);
      return Response.json({ ok: true, override: override || null });
    }

    if (url.pathname.startsWith("/media/pending/")) {
      const adminId = decodeURIComponent(String(url.pathname.split("/").pop() || ""));
      if (!/^\d+$/.test(adminId)) return Response.json({ ok: false, error: "bad admin id" }, { status: 400 });
      const key = `managed-media-pending-v1-${adminId}`;
      if (request.method === "POST") {
        const pending = await request.json().catch(() => null);
        if (!pending?.type || !MANAGED_POST_MEDIA[pending.type] || !pending.expiresAt) {
          return Response.json({ ok: false, error: "bad pending upload" }, { status: 400 });
        }
        await this.state.storage.put(key, pending);
        return Response.json({ ok: true, pending });
      }
      if (request.method === "DELETE") {
        await this.state.storage.delete(key);
        return Response.json({ ok: true, pending: null });
      }
      const pending = await this.state.storage.get(key);
      if (pending && Date.parse(pending.expiresAt || "") <= Date.now()) {
        await this.state.storage.delete(key);
        return Response.json({ ok: true, pending: null });
      }
      return Response.json({ ok: true, pending: pending || null });
    }

    if (url.pathname === "/article/history") {
      if (request.method === "POST") {
        const history = await request.json();
        await this.state.storage.put("article-history-v1", history);
        return Response.json({ ok: true });
      }
      const history = await this.state.storage.get("article-history-v1");
      return Response.json({ ok: true, history: history || { used: [], last: "" } });
    }
    if (request.method === "POST" && url.pathname === "/mode/live") {
      await this.state.storage.put("mode", "live");
      return Response.json({ ok: true, mode: "live" });
    }
    if (request.method === "POST" && url.pathname === "/mode/test") {
      await this.state.storage.put("mode", "test");
      return Response.json({ ok: true, mode: "test" });
    }
    const mode = await this.state.storage.get("mode");
    return Response.json({ ok: true, mode: mode === "live" ? "live" : "test" });
  }
};
